private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (i < bb.remaining()) {
        int c = bb.get(i) & 0xFF;
        if (c >= 0 && c <= 127) {
            sb.append((char)c);
            i++;
        } else if (c >= 194 && c <= 223) {
            i += 2;
            c &= ~32;
            sb.append((char)((c & 0x7) << 6 | (bb.get(i) & 0xFF) & 0x3F));
        } else if (c == 224) {
            i += 3;
            c &= ~16;
            sb.append((char)((c & 0xF) << 12 | (bb.get(i) & 0xFF) & 0x3F | (bb.get(i + 1) & 0xFF) << 6));
        } else if (c == 225) {
            i += 4;
            sb.append((char)((c & 0x7) << 18 | (bb.get(i) & 0xFF) & 0x3F | (bb.get(i + 1) & 0xFF) << 12 | (bb.get(i + 2) & 0xFF) << 6 | (bb.get(i + 3) & 0xFF) << 18));
        } else {
            // handle invalid octets here
            i++;
        }
    }
    return i;
}

