private void enlarge(int size) {
    // Ensure that this byte vector can receive at least 'size' more bytes
    if (this.array.length - this.offset < size) {
        int capacity = this.array.length;
        while (capacity < size) {
            capacity *= 2;
        }
        byte[] newArray = new byte[capacity];
        System.arraycopy(this.array, 0, newArray, 0, this.offset);
        this.array = newArray;
    }
}

