private int parseEndOfLine(String headerPart, int end) {
    // Find the next \r\n sequence
    int cr = headerPart.indexOf('\r', end);
    if (cr != -1) {
        int lf = headerPart.indexOf('\n', cr + 1);
        if (lf != -1) {
            return lf + 1; // \r\n sequence found
        } else {
            return cr; // Only \r found
        }
    } else {
        return end; // No \r\n sequence found
    }
}

