public Mappings diffStructure(String tableName, Mappings mappings) {
    // Retrieve the historic mapping for the specified table
    Mappings historicMappings = getHistoricMapping(tableName);

    // Get the fields that exist in the input mappings but not in the historic mappings
    Set<String> newFields = mappings.getFields().stream()
            .filter(field -> historicMappings.getFields().contains(field))
            .collect(Collectors.toSet());

    // Get the fields that exist in the historic mappings but not in the input mappings
    Set<String> deletedFields = historicMappings.getFields().stream()
            .filter(field -> mappings.getFields().contains(field))
            .collect(Collectors.toSet());

    // Create a new mapping with the added and deleted fields
    Mappings diffMappings = new Mappings( historicMappings.getDate(),
            historicMappings.getIgnoredGroups(),
            historicMappings.getGroups(),
            historicMappings.getFields().stream()
                    .filter(field -> !deletedFields.contains(field))
                    .collect(Collectors.toSet()),
            mappings.getFields().stream()
                    .filter(field -> !newFields.contains(field))
                    .collect(Collectors.toSet())
    );

    return diffMappings;
}

