public static Character convertToType(Class<?> type, Object value) throws Exception {
  if (type.equals(Character.class) || type.equals(char.class)) {
    return (Character) value;
  }
  if (type.equals(String.class)) {
    return value.toString().charAt(0);
  }
  if (type.equals(Boolean.class) || type.equals(boolean.class)) {
    return (Boolean) value ? (char) 1 : (char) 0;
  }
  if (type.equals(Byte.class) || type.equals(byte.class)) {
    return (byte)((Number) value).intValue();
  }
  if (type.equals(Short.class) || type.equals(short.class)) {
    return (short)((Number) value).intValue();
  }
  if (type.equals(Integer.class) || type.equals(int.class)) {
    return (int)((Number) value).intValue();
  }
  if (type.equals(Long.class) || type.equals(long.class)) {
    return (long)((Number) value).longValue();
  }
  if (type.equals(BigDecimal.class)) {
    return new BigDecimal(value.toString());
  }
  if (type.equals(BigInteger.class)) {
    return new BigInteger(value.toString());
  }
  throw new Exception("Unsupported type: " + type.getName());
}

