public short readShort(int offset) {
    // Check if we are at the end of the file
    if (offset + 2 > readableBytes()) {
        throw new IllegalStateException("Cannot read short at offset " + offset + " and length " + 2 + ": End of file reached");
    }

    // Read the short value at the specified offset
    short value = 0;
    for (int i = 0; i < 2; i++) {
        int bits = inputStream().read();
        if (bits == -1) {
            throw new IllegalStateException("Cannot read short at offset " + offset + " and length " + 2 + ": Premature EOF");
        }
        value = (short) (value | (bits << (8 * i)));
    }

    // Move the offset to the first byte of the next four-byte word
    offset += 2;

    return value;
}

