        // Get the source and target vertices of the edge
        V src = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        // Add the edge to the graph path, using the source and target vertices
        gp.addEdge(edge, src, target);
    }

    // Return the constructed graph path
    return gp;
}

