private String parseToken(char[] terminators) {
  // Initialize the empty token string
  String token = "";
  // Iterate over the input string
  for (int i = 0; i < input.length(); i++) {
    // Check if the current character is a terminator
    if (terminators.contains(input.charAt(i))) {
      // If so, break the loop
      break;
    } else {
      // If not, add the character to the token string
      token += input.charAt(i);
    }
  }
  return token;
}

