    for (E edge : graph.getEdges()) {
        // Compute the minimal separators of the edge's neighborhood
        List<Pair<Integer, Integer>> minSeparators = computeMinSeparators(edge);

        // If the edge has at least one minimal separator, add it to the global separator list
