private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> lowerBounds = new ArrayList<>();
    for (K key : keys) {
        // Find the maximum lower bound for the current key
        int lowerBound = 0;
        for (int i = 0; i < keys.size(); i++) {
            if (keys.get(i).compareTo(key) < 0) {
                lowerBound = i + 1;
            }
        }
        lowerBounds.add(lowerBound);
    }
    return lowerBounds;
}

private void pop(final String descriptor) {
    switch (descriptor.charAt(0)) {
        case '[':
            // array type
            // pop elements
            for (int i = 0; i < descriptor.charAt(1); i++) {
                pop();
            }
            // pop array object
            pop();
            break;
        case 'L':
            // object type
            // pop fields
            for (int i = 1; i < descriptor.length(); i++) {
                pop();
            }
            // pop object
            pop();
            break;
        default:
            // primitive type
            pop();
            break;
    }
}

