private List<Integer> computeUpperBounds(List<K> keys) {
    // Step 1. Sort the keys
    List<K> sortedKeys = new ArrayList<>(keys);
    sortedKeys.sort(Comparator.naturalOrder());

    // Step 2. Find the upper bounds
    List<Integer> upperBounds = new ArrayList<>();
    for (int i = 1; i < sortedKeys.size(); i++) {
        K currentKey = sortedKeys.get(i);
        K previousKey = sortedKeys.get(i - 1);
        int currentLength = currentKey.length();
        int previousLength = previousKey.length();
        int maxLength = Math.max(currentLength, previousLength);
        int minLength = Math.min(currentLength, previousLength);
        for (int j = 0; j < minLength; j++) {
            if (currentKey.charAt(j) != previousKey.charAt(j)) {
                upperBounds.add(j);
                break;
            }
        }
        if (minLength == maxLength) {
            upperBounds.add(minLength);
        }
    }

    // Step 3. Return the upper bounds
    return upperBounds;
}

